/*
 Problem: 3718. Smallest Missing Multiple of K
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 23.9 MB (99.59%)
 Tags: Array, Hash Table
*/
class Solution {
public:
    int missingMultiple(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());

        int target = k;

        for (const auto& x : nums) {
            if (x == target)
                target += k;
        }

        return target;
    }
};
